INSERT INTO book (id_book, isbn, title, author, publication_date, price, gender, editor, bookimage, vignetteimage, age_limit, description, created_at, updated_at, series)
VALUES 
('1a2b3c4d-5e6f-7g8h-9i0j-1k2l3m4n5o6p', '978-2017080251', '1984', 'George Orwell', '2001-01-01', 13.93, 'Dystopie', 'Folio', 'images/booksImages/1984_Georges_Orwell.png', 'images/vignettesImages/1984_Georges_Orwell.png', 12, 'Winston Smith a trente-neuf ans et travaille pour le Parti, au ministère de la Vérité. Ses tâches ? Réécrire les archives pour que le passé corresponde à la version dictée par le gouvernement. Winston est doué, mais sa conscience commence lentement à lui peser. Il a de plus en plus de mal à croire aux mensonges du monde qui l’entoure, et il décide de se rebeller. D''abord, il se met à écrire un journal, puis il se rapproche de Julia. Mais la Police de la Pensée est toujours plus près qu’il n’y paraît, et la surveillance plus étroite.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('2b3c4d5e-6f7g-8h9i-0j1k-2l3m4n5o6p7q', '978-2070612758', 'Le Petit Prince', 'Antoine de Saint-Exupéry', '2020-01-01', 18.08, 'Conte', 'Plon', 'images/booksImages/le_petit_prince.png', 'images/vignettesImages/le_petit_prince.png', 18, 'Le premier soir, je me suis donc endormi sur le sable à mille milles de toute terre habitée. J''étais bien plus isolé qu''un naufragé sur un radeau au milieu de l''océan. Alors, vous imaginez ma surprise, au lever du jour, quand une drôle de petite voix m''a réveillé. Elle disait : "S''il vous plaît...dessine-moi un mouton !" J''ai bien regardé. Et j''ai vu ce petit bonhomme tout à fait extraordinaire qui me considérait gravement..." La version originale du chef-d''oeuvre de Saint-Exupéry, suivie d''un cahier spécial pour aller à la rencontre de l''auteur.', '2025-01-02 11:00:00', '2025-01-02 12:00:00', 'one shot'),
('3c4d5e6f-7g8h-9i0j-1k2l-3m4n5o6p7q8w', '978-2070360024', 'L''Étranger', 'Albert Camus', '1995-01-01', 10.66, 'Philosophie', 'Plon', 'images/booksImages/letranger.png', 'images/vignettesImages/letranger.png', 10, 'Quand la sonnerie a encore retenti, que la porte du box s''est ouverte, c''est le silence de la salle qui est monté vers moi, le silence, et cette singulière sensation que j''ai eue lorsque j''ai constaté que le jeune journaliste avait détourné les yeux. Je n''ai pas regardé du côté de Marie. Je n''en ai pas eu le temps parce que le président m''a dit dans une forme bizarre que j''aurais la tête tranchée sur une place publique au nom du peuple français...', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('4d5e6f7g-8h9i-0j1k-2l3m-4n5o6p7q8r9s', '978-2075187541', 'Harry Potter à l''école des sorciers', 'J.K. Rowling', '1978-01-01', 11.91, 'Fantasy', 'Le Livre de Poche', 'images/booksImages/lecole_des_sorciers.png', 'images/vignettesImages/lecole_des_sorciers.png', 10, 'Le jour de ses onze ans, Harry Potter, un orphelin élevé par un oncle et une tante qui le détestent, voit son existence bouleversée. Un géant vient le chercher pour l''emmener à Poudlard, une école de sorcellerie ! Voler en balai, jeter des sorts, combattre les trolls : Harry révèle de grands talents. Mais un mystère entoure sa naissance et l''effroyable V., le mage dont personne n''ose prononcer le nom.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', '1 sur 7'),
('5e6f7g8h-9i0j-1k2l-3m4n-5o6p7q8r9s0t', '978-2266296144', 'Les Misérables', 'Victor Hugo', '2013-01-01', 12.08, 'Historique', 'Actes Sud', 'images/booksImages/les_miserables.png', 'images/vignettesImages/les_miserables.png', 18, 'Peut-on imaginer un monde sans Jean Valjean, Cosette, Gavroche, Javert ou Fantine, à jamais vivants au Panthéon de l''esprit humain ?En 1862 paraissent Les Misérables, qui désignent toutes les vicitmes d''un ordre social dont Victor Hugo condamne les injustices. Immense épopée populaire, le roman est emporté dans l''air de Paris et de ses bas-fonds, chargé de l''odeur des barricades et de la Révolution. Il deviendra l''une des oeuvres les plus lues dans le monde. On dit que lorsque les premières épreuves sortirent des presses, les correcteurs et les imprimeurs pleuraient.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('6f7g8h9i-0j1k-2l3m-4n5o-6p7q8r9s0t1u', '978-2709624930', 'Da Vinci Code', 'Dan Brown', '1992-01-01', 22.69, 'Thriller', 'Folio', 'images/booksImages/da_vinci_code.png', 'images/vignettesImages/da_vinci_code.png', 18, 'De passage à Paris, Robert Langdon, professeur à Havard et spécialiste de symbologie, est appelé d''urgence au Louvre, en pleine nuit. Jacques Saunière, le conservateur en chef a été retrouvé assassiné au milieu de la Grande Galerie. Au côté du cadavre, la police a trouvé un message codé. Langdon et Sophie Neveu, une brillante cryptographe membre de la police, tentent de le résoudre. Ils sont stupéfaits lorsque les premiers indices le conduisent à l''oeuvre de Léonard de Vinci. Ils découvrent également que Saunière était membre du Prieuré de Sion, une société secrète dont avaient fait partie Nexton, Boticelli, Léonardo da Vinci, Victor Hugo, et qu''il protégeait un secret millénaire. L''enquête de nos deux héros les entraînera à travers la France et le Royaume-Uni, non seulement pour chercher une vérité longtemps cachée concernant la Chrétienté, mais également pour échapper à ceux qui voudraient s''emparer du secret. Pour réussir, il leur faut résoudre de nombreuses énigmes, et vite, sinon le secret risque d''être perdu à tout jamais.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', '1 sur 4'),
('7g8h9i0j-1k2l-3m4n-5o6p-7q8r9s0t1u2v', '978-2266282376', 'Le Seigneur des Anneaux, les deux tours', 'J.R.R. Tolkien', '1971-01-01', 24.58, 'Fantasy', 'Le Livre de Poche', 'images/booksImages/le_seigneur_des_anneaux_2_tours.png', 'images/vignettesImages/le_seigneur_des_anneaux_2_tours.png', 18, 'Les neux compagnons avaient fondé la Fraternité de l''Anneau, tous soudés autour de Frodo, dépositaire de l''Anneau de Pouvoir, chargé de le détruire en le jetant dans la Montagne du Feu, où il fut forgé par son maître. Mais c''est là une quête terrible et semée d''embûches. Leur guide, Gandalf, a disparu, Boromir, comme pris de folie, a voulu s''emparer de l''Anneau, Frodo a dû s''échapper et poursuit, esseulé, mais déterminé, son voyage jusqu''au cœur du Mordor. La Fraternité est dissoute, les Ténèbres s''étendent toujours plus, et l''avenir de la Terre du Millieu repose sur les frêles épaules d''un courageux petit Hobbit.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', '2 sur 3'),
('8h9i0j1k-2l3m-4n5o-6p7q-8r9s0t1u2v3w', '979-1093835600', 'Orgueil et Préjugés', 'Jane Austen', '2017-01-01', 24.67, 'Romance', 'Plon', 'images/booksImages/orgeuils_et_prejuges.png', 'images/vignettesImages/orgeuils_et_prejuges.png', 14, 'Issue d''une famille de la petite gentry anglaise, Elizabeth Bennet ne manque ni d''humour ni de malice. Lors d''un bal, elle rencontre le hautain Mr Darcy, un des hommes les plus riches d''Angleterre mais aussi l''un des plus orgueilleux, qu''elle méprise aussitôt. Après avoir mal jugé le charme de la jeune femme, il tombe amoureux d''elle et mènera une longue lutte intérieure entre ce que lui dictent son coeur et son rang. Comment réussiront-ils à vaincre leurs préjugés et à faire taire leur orgueil pour connaître l''amour ?', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('9i0j1k2l-3m4n-5o6p-7q8r-9s0t1u2v3w4x', '978-2266341233', 'Le Hobbit', 'J.R.R. Tolkien', '1966-01-01', 20.34, 'Fantasy', 'Gallimard', 'images/booksImages/le_hobbit.png', 'images/vignettesImages/le_hobbit.png', 16, 'Le Hobbit rejoint la collection Pocket Imaginaire en version collector Bilbo, comme tous les hobbits, est un petit être paisible et sans histoire. Son quotidien est bouleversé un beau jour, lorsque Gandalf le magicien et treize nains barbus l''entraînent dans un voyage périlleux. C''est le début d''une grande aventure, d''une fantastique quête au trésor semée d''embûches et d''épreuves, qui mènera Bilbo jusqu''à la Montagne Solitaire gardée par le dragon Smaug...', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'prequel'),
('0j1k2l3m-4n5o-6p7q-8r9s-0t1u2v3w4x5y', '979-1035801823', 'Fahrenheit 451', 'Ray Bradbury', '1997-01-01', 10.87, 'Science-fiction', 'Le Livre de Poche', 'images/booksImages/fahrenheit_451.png', 'images/vignettesImages/fahrenheit_451.png', 12, 'Traduction de J. Chambon et H. Robillot. Dossier pédagogique de M.-É. Papet. Dans une société futuriste, les pompiers brûlent les livres. Une contre-utopie qui invite à réfléchir sur le pouvoir des médias et les dangers de la censure. Dans le volume, des prolongements pour étudier le genre de la science-fiction en littérature et au cinéma. Groupements de textes : 1. Des univers imaginaires pour critiquer notre société 2. La lecture et ses dangers', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('a1b2c3d4-e5f6-7g8h-9i0j-1k2l3m4n5o6p', '978-0099419785', 'To Kill a Mockingbird', 'Harper Lee', '1978-01-01', 5.8, 'Historique', 'Actes Sud', 'images/booksImages/To_Kill_a_Mockingbird.png', 'images/vignettesImages/To_Kill_a_Mockingbird.png', 16, '« Tirez sur tous les geais bleus que vous voulez, si vous pouvez les toucher, mais rappelez-vous que tuer un oiseau moqueur est un péché. » L''avocat Atticus Finch donne ce conseil à ses enfants en défendant le véritable oiseau moqueur du roman classique de Harper Lee : un homme noir accusé du viol d''une jeune fille blanche. À travers les yeux juvéniles de Scout et Jem Finch, Harper Lee explore avec un humour exubérant l''irrationalité des attitudes des adultes envers la race et la classe sociale dans le Sud profond des années 1930. La conscience d''une ville imprégnée de préjugés, de violence et d''hypocrisie est touchée par l''endurance du combat d''un homme pour la justice. Mais le poids de l''histoire a ses limites… Référence de la littérature américaine classique, « Du silence à l''oiseau moqueur » aborde le sujet très sensible du racisme dans l''Amérique des années 1930 avec humour, chaleur et compassion, ce qui lui vaut d''être largement reconnu comme l''un des meilleurs livres du XXe siècle et de la littérature américaine.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('b2c3d4e5-f6g7-8h9i-0j1k-2l3m4n5o6p7a', '978-2253007104', 'Les Fleurs du mal', 'Charles Baudelaire', '2015-01-01', 13.08, 'Poésie', 'Actes Sud', 'images/booksImages/Les_Fleurs_du_mal.png', 'images/vignettesImages/Les_Fleurs_du_mal.png', 10, 'Avec Les Fleurs du Mal commence la poésie moderne : le lyrisme subjectif s''efface devant cette « impersonnalité volontaire » que Baudelaire a lui-même postulée ; la nature et ses retours cycliques cèdent la place au décor urbain et à ses changements marqués par l''Histoire, et il arrive que le poète accède au beau par l''expérience de la laideur. Quant au mal affiché dès le titre du recueil, s''il nous apporte la preuve que l''art ici se dénoue de la morale, il n''en préserve pas moins la profonde spiritualité des poèmes. D''où la stupeur que Baudelaire put ressentir quand le Tribunal de la Seine condamna la première édition de 1857 pour « outrage à la morale publique et aux bonnes moeurs » et l''obligea à retrancher six pièces du volume - donc à remettre en cause la structure du recueil qu''il avait si précisément concertée. En 1861, la seconde édition fut augmentée de trente-cinq pièces, puis Baudelaire continua d''écrire pour son livre d''autres poèmes encore. Mais après la censure, c''est la mort qui vint l''empêcher de donner aux Fleurs du Mal la forme définitive qu''il souhaitait - et que nous ne connaîtrons jamais.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('c3d4e5f6-g7h8-9i0j-1k2l-3m4n5o6p7q8r', '978-2090318883', 'Le Comte de Monte-Cristo', 'Alexandre Dumas', '1967-01-01', 6.56, 'Aventure', 'Folio', 'images/booksImages/Le_Comte_de_Monte-Cristo.png', 'images/vignettesImages/Le_Comte_de_Monte-Cristo.png', 16, 'Quand Edmond Dantes arrive au port de Marseille, tout lui sourit : il va être nommé capitaine du navire Le Pharaon et il est aimé de la belle Mercédès. Malheureusement, un horrible complot mettra fin à ce bel avenir. Après plusieurs années passées dans la prison du château d''If, Dantés renaîtra sous les traits du comte de Monte-Cristo pour accomplir sa terrible vengeance.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', '1 sur 2'),
('d4e5f6g7-h8i9-0j1k-2l3m-4n5o6p7q8r9a', '978-2253009009', 'Bel-Ami', 'Guy de Maupassant', '2005-01-01', 17.61, 'Classique', 'Plon', 'images/booksImages/Bel-Ami.png', 'images/vignettesImages/Bel-Ami.png', 18, 'A qui Georges Duroy doit-il son irrésistible ascension ? Aux femmes séduites par sa jeunesse et sa beauté. La petite fille de l''une de ses maîtresses le surnommera Bel-Ami. Et ce fils d''aubergistes normands, à Canteleu, deviendra baron Du Roy de Cantel. L''amitié lui ouvrira la carrière journalistique. L''amour lui donnera l''argent et la gloire. Maupassant a été journaliste. Il a connu ce monde parisien du xixe siècle, les salles de rédaction qui font et défont les ministères, et leurs annexes, les salons mondains où naissent intrigues et liaisons. Ses portraits de femmes dévorées d''amour ou d''ambition, ses tableaux de la vallée de la Seine à Rouen, ses fiacres, avenue du Bois de Boulogne, sont oeuvre de peintre. Maupassant était un maître du récit.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('e5f6g7h8-i9j0-1k2l-3m4n-5o6p7q8r9s0a', '978-2080452269', 'L’Alchimiste', 'Paulo Coelho', '1970-01-01', 9.96, 'Spiritualité', 'Gallimard', 'images/booksImages/L’Alchimiste.png', 'images/vignettesImages/L’Alchimiste.png', 16, 'Mon coeur craint de souffrir, dit le jeune homme à l''Alchimiste, une nuit qu''ils regardaient le ciel sans lune. - Dis-lui que la crainte de la souffrance est pire que la souffrance elle-même. Et qu''aucun coeur n''a jamais souffert alors qu''il était à la poursuite de ses rêves." Santiago, jeune berger andalou, part à la recherche d''un trésor enfoui au pied des Pyramides. Lorsqu''il rencontre l''Alchimiste dans le désert, celui-ci lui apprend à écouter son coeur, à lire les signes du destin et, par-dessus tout, à aller au bout de son rêve. Merveilleux conte philosophique destiné à l''enfant qui sommeille en chacun de nous, L''Alchimiste a marqué des millions de lecteurs. À l''occasion des trente ans de sa publication en France, cette édition anniversaire illustrée par Christoph Niemann célèbre le livre iconique de Paulo Coelho et nous invite à le redécouvrir.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('f6g7h8i9-j0k1-2l3m-4n5o-6p7q8r9s0t1a', '978-2070349579', 'La Peste', 'Albert Camus', '1992-01-01', 5.01, 'Philosophie', 'Folio', 'images/booksImages/La_Peste.png', 'images/vignettesImages/La_Peste.png', 10, 'Naturellement, vous savez ce que c''est, Rieux? - J''attends le résultat des analyses. - Moi, je le sais. Et je n''ai pas besoin d''analyses. J''ai fait une partie de ma carriere en Chine, et j''ai vu quelques cas a Paris, il y a une vingtaine d''années. Seulement, on n''a pas osé leur donner un nom, sur le moment... Et puis, comme disait un confrere : "C''est impossible, tout le monde sait qu''elle a disparu de l''Occident." Oui, tout le monde le savait, sauf les morts. Allons, Rieux, vous savez aussi bien que moi ce que c''est... - Oui, Castel, dit-il, c''est a peine croyable. Mais il semble bien que ce soit la peste.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('g7h8i9j0-k1l2-3m4n-5o6p-7q8r9s0t1u2e', '978-2253033134', 'Le Nom de la Rose', 'Umberto Eco', '1965-01-01', 13.9, 'Policier', 'Plon', 'images/booksImages/Le_Nom_de_la_Rose.png', 'images/vignettesImages/Le_Nom_de_la_Rose.png', 14, 'En l’an de grâce et de disgrâce 1327, rien ne va plus dans la chrétienté. Des bandes d''hérétiques sillonnent les royaumes. Lorsque Guillaume de Baskerville, accompagné de son secrétaire, arrive dans le havre de sérénité et de neutralité qu''est l''abbaye située entre Provence et Ligurie – que tout l''Occident admire pour la science de ses moines et la richesse de sa bibliothèque –, il est aussitôt mis à contribution par l’abbé. La veille, un moine s’est jeté du haut des murailles. C’est le premier des assassinats qui seront scandés par les heures canoniales de la vie monastique. Crimes, stupre, vice, hérésie, tout va advenir en l’espace de sept jours.Sous sa forme amusante de roman policier et savante de devinette érudite, un vibrant plaidoyer pour la liberté, pour la mesure, pour la sagesse, menacées de tous côtés par les forces de la déraison et de la nuit. Dominique Fernandez, L’Express.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('h8i9j0k1-l2m3-4n5o-6p7q-8r9s0t1u2v3p', '978-2070668472', 'Germinal', 'Émile Zola', '2016-01-01', 16.27, 'Historique', 'Gallimard', 'images/booksImages/germinal.png', 'images/vignettesImages/germinal.png', 12, 'Étienne Lantier trouve un emploi de mineur à Montsou, dans le Nord de la France. Les payes sont misérables, les conditions de travail effroyables : chaleur étouffante, obscurité, risques d''éboulement... Quand la Compagnie décide de réduire encore les salaires, la colère gronde dans les corons. Lantier prend la tête de la révolte. En version abrégée, la grande fresque de Zola sur le monde de la mine au XIXe siècle.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('i9j0k1l2-m3n4-5o6p-7q8r-9s0t1u2v3w4z', '978-2221157480', 'L’Attrape-cœurs', 'J.D. Salinger', '1987-01-01', 12.73, 'Roman initiatique', 'Gallimard', 'images/booksImages/LAttrape_cœurs.png', 'images/vignettesImages/LAttrape_cœurs.png', 18, 'Issu d''une famille aisée à New York, Holden Caulfield intègre le pensionnat Pencey Prep en Pennsylvanie. Renvoyé après avoir échoué dans quatre matières, il entreprend alors une aventure de délinquance innocente. Entre taxis, boîtes de jazz et rencontres au sein du New York transi de froid de l''époque McCarthy, Holden va tenter de trouver sa place.Une histoire captivante qui dresse un portrait incontournable de l''Amérique de l''après-guerre au travers de l''un des personnages les plus aimés de la littérature.Après soixante ans, L''Attrape-cœurs, premier et unique roman de J. D. Salinger conserve toute sa puissance. Objet de réflexions sur la souffrance de l''adolescence et la transition de l''enfance à l''âge adulte, le livre reste un classique incontournable pour les jeunes de tous âges.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('j0k1l2m3-n4o5-6p7q-8r9s-0t1u2v3w4x5o', '978-2234046399', 'Le Parfum', 'Patrick Süskind', '2015-01-01', 18.32, 'Drame', 'Actes Sud', 'images/booksImages/Le_Parfum.png', 'images/vignettesImages/Le_Parfum.png', 18, 'Au XVIIIe siècle vécut en France un homme qui compta parmi les personnages les plus géniaux et les plus horribles de son époque. Il s''appelait Jean-Baptiste Grenouille. Sa naissance, son enfance furent épouvantables et tout autre que lui n''aurait pas survécu. Mais Grenouille n''avait besoin que d''un minimum de nourriture et de vêtements, et son âme n''avait besoin de rien. Or ce monstre de Grenouille, car il s''agissait bel et bien d''un genre de monstre, avait un don, ou plutôt un nez unique au monde et il entendait bien devenir, même par les moyens les plus atroces, le Dieu tout-puissant de l''univers, car « qui maîtrisait les odeurs, maîtrisait le coeur des hommes ». C''est son histoire, abominable… et drolatique, qui nous est racontée dans Le Parfum, un roman très vite devenu un best-seller mondial, et aujourd''hui porté à l''écran.', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('3c4d5e6f-7g8h-9i0j-1k2l-3m4n5o6p7q7r', '978-2211124485', 'L’Odyssée', 'Homère', '2000-01-01', 15.99, 'Épopée', 'Gallimard', 'images/booksImages/L’Odyssée.png', 'images/vignettesImages/L’Odyssée.png', 16, 'Dans la petite île d''Ithaque, Pénélope et son fils Télémaque attendent Ulysse, leur époux et père. Voilà vingt ans qu''il est parti pour Troie et qu''ils sont sans nouvelles de lui. De l''autre côté des mers, Ulysse a pris le chemin du retour depuis longtemps déjà. Mais les tempêtes, les monstres, les géants, les dieux parfois, l''arrêtent ou le détournent de sa route. Premier grand voyageur, Ulysse découvre l''inconnu où naissent les rêves et les peurs des hommes depuis la nuit des temps; l''Odyssée nous dit cette aventure au terme de laquelle le héros retrouve enfin, aux côtés de Pénélope, « la joie du lit ancien ».', '2025-01-01 12:00:00', '2025-01-01 13:00:00', 'one shot'),
('1f2g3h4i-5j6k-7l8m-9n0o-1p2q3r4s5t6u', '978-2755673203', 'mad mejesty', 'melinda', '2023-01-01', 15.99, 'Fantasy', 'Gallimard', 'images/booksImages/mad_mejesty.png', 'images/vignettesImages/mad_mejesty.png', 16, 'Assumer le poids de la couronne, mais à quel prix ? Depuis son retour de l’armée, le prince Damian enchaîne les scandales en tout genre. Qu’importe la volonté de sa famille, impossible de le faire rentrer dans le rang. Il fait régulièrement la une des tabloïds, jetant le discrédit sur la couronne. Alors quand le roi décède et que le prince héritier est appelé à monter sur le trône, c’est toute la monarchie qui est ébranlée. La seule manière de sauver les apparences ? Un mariage, avec celle que sa mère lui a choisie : Ophélia St John, une future épouse obéissante et malléable. En somme, parfaite pour le rôle. Mais Damian n’entend pas se plier de bon gré à ce jeu de dupes. Si l’institution lui impose des fiançailles, il compte bien choisir qui il épousera. Et cela sera Esmée St John, la petite sœur de celle qui a été élevée pour régner. Synesthète, sarcastique, mais profondément humaine et empathique, Esmée parviendra-t-elle à ravir les cœurs du royaume ou précipitera-t-elle sa chute ?', '2025-01-01 10:00:00', '2025-01-01 11:00:00', 'one shot'),
('2g3h4i5j-6k7l-8m9n-0o1p-2q3r4s5t6u7v', '978-2017206996', 'trouble maker', 'laura swan', '2022-05-15', 12.50, 'Romance', 'Plon', 'images/booksImages/trouble_maker.png', 'images/vignettesImages/trouble_maker.png', 14, 'Patienter. C’est le quotidien étouffant de June. Elle n’a plus qu’un an à passer dans son prestigieux lycée privé, un an à affronter le harcèlement constant des autres élèves. Un an à survivre dans une maison où elle n’a pas sa place, et où la violence sature l’air. Une nuit, lorsqu’elle est seule chez elle, des voleurs s’introduisent. L’un d’entre eux la repère et lui ordonne de se taire, lui sauvant ainsi la vie. Alors que des mois plus tard, cet épisode semble oublié, un nouvel enseignant fait son apparition dans son lycée. Ce remplaçant n’est autre que le cambrioleur l’ayant épargnée cette nuit-là. Shayn, qui s’est exilé à Londres suite à une série de mauvais choix, se voit désormais confronté à June, témoin d’un passé qu’il avait laissé derrière lui. Pour s’assurer de son silence, il est prêt à toutes sortes d’intimidations. Mais June n’a pas l’intention de céder. Car si Shayn est déterminé à garder ses secrets, elle se bat aussi pour préserver les siens.', '2025-01-02 11:00:00', '2025-01-02 12:00:00', 'one shot'),
('3h4i5j6k-7l8m-9n0o-1p2q-3r4s5t6u7v8w', '978-2035969200', 'un rien peut tout changer', 'James Clear', '2021-09-10', 18.99, 'Développement personnel', 'Folio', 'images/booksImages/un_rien_peut_tout_changer.png', 'images/vignettesImages/un_rien_peut_tout_changer.png', 12, 'Vous avez du mal à changer vos habitudes ? Le problème ne vient pas de vous, mais des moyens que vous utilisez. Les mauvaises habitudes se répètent non pas parce que vous ne voulez pas changer, mais parce que vous utilisez des moyens incompatibles avec le changement. Un rien peut tout changer vous propose une méthode efficace qui va bousculer vos habitudes ! Quels que soient vos objectifs, ce livre vous apporte les clés pour vous améliorer progressivement, grâce à de petits changements quotidiens. Il vous offre des stratégies pratiques vous permettant de parfaitement maîtriser d’infimes actions menant à des résultats concrets. Créez de bonnes habitudes, abandonnez les mauvaises ! Expert mondial en matière de création d’habitudes, James Clear est réputé pour sa capacité à transformer des processus complexes en comportements simples facilement applicables à la vie quotidienne et au travail. Il s’appuie sur des concepts issus de la biologie, de la psychologie et des neurosciences pour vous aider à modifier vos agissements. Emaillé d’histoires vraies, Un rien peut tout changer transforme radicalement votre vision du progrès et vous donne les techniques nécessaires pour changer enfin vos habitudes ! James Clear est un auteur et conférencier spécialiste des habitudes, de la prise de décision et de l’amélioration continue. Ses travaux sont régulièrement publiés dans le New York Times, Time et Entrepreneur ; il participe également à CBS This Morning. The Habits Academy est la première plateforme de formation destinée aux particuliers et professionnels souhaitant développer de meilleures habitudes au quotidien.', '2025-01-03 12:00:00', '2025-01-03 13:00:00', 'one shot'),
('4i5j6k7l-8m9n-0o1p-2q3r-4s5t6u7v8w9x', '978-2755677508', 'insomnia the royal thorns', 'Lea nemezia', '2020-11-20', 20.00, 'Thriller', 'Actes Sud', 'images/booksImages/insomnia_the_royal_thorns.png', 'images/vignettesImages/insomnia_the_royal_thorns.png', 16, 'La romance dark academia qui a conquis les lecteurs sur Wattpad Lorsque Skyler fait sa rentrée sur le mythique campus d’Oxford, elle aspire à débuter une nouvelle vie pleine de promesses loin de sa famille menaçante. Guidée par sa soif de découvertes, elle ne tarde pas à se rendre compte que le campus cache bien plus de secrets qu’il n’y paraît. Et qu’il n’est pas bon de chercher à les percer. Sa rencontre nocturne avec un mystérieux homme dont l’identité est dissimulée sous un masque de squelette la plonge dans un univers où les sociétés secrètes règnent en maître, entre élitisme et opulence. Dès lors qu’elle croise le regard bleu glacier de cet étudiant, il lui est impossible de faire machine arrière. Qui est-il ? Et pourquoi a-t-elle l’impression que ce n’est pas la première fois qu’elle croise sa route ? Tous les vilains démons d’Oxford cachent un sombre secret. Jusqu’où sont-ils prêts à aller pour les dissimuler?', '2025-01-04 13:00:00', '2025-01-04 14:00:00', 'one shot'),
('5j6k7l8m-9n0o-1p2q-3r4s-5t6u7v8w9x0y', '978-2253934103', 'tout le bleu du ciel', 'Melissa da costa', '2019-03-01', 22.50, 'Contemporain', 'Gallimard', 'images/booksImages/tout_le_bleu_du_ciel.png', 'images/vignettesImages/tout_le_bleu_du_ciel.png', 14, 'Petitesannonces.fr : Jeune homme de 26 ans, condamné à une espérance de vie de deux ans par un Alzheimer précoce, souhaite prendre le large pour un ultime voyage. Recherche compagnon(ne) pour partager avec moi ce dernier périple. Émile a décidé de fuir l’hôpital, la compassion de sa famille et de ses amis. À son propre étonnement, il reçoit une réponse à cette annonce. Trois jours plus tard, devant le camping-car acheté secrètement, il retrouve Joanne, une jeune femme coiffée d’un grand chapeau noir qui a pour seul bagage un sac à dos, et qui ne donne aucune explication sur sa présence. Ainsi commence un voyage stupéfiant de beauté. À chaque détour de ce périple naissent, à travers la rencontre avec les autres et la découverte de soi, la joie, la peur, l’amitié, l’amour qui peu à peu percent la carapace de douleurs d’Émile. Un livre aux dialogues impeccables et aux personnages touchants d’humanité. Psychologies magazine. Bouleversant. ', '2025-01-05 14:00:00', '2025-01-05 15:00:00', 'one shot'),
('6k7l8m9n-0o1p-2q3r-4s5t-6u7v8w9x0y1z', '978-2226470089', 'Prime time', 'Maxime chattam', '2018-07-15', 19.99, 'Policier', 'Plon', 'images/booksImages/prime_time.png', 'images/vignettesImages/prime_time.png', 18, 'Alors que des millions de téléspectateurs regardent le 20h sur la chaîne nationale, un homme masqué, la voix déformée, prend en otage le présentateur vedette. Si le direct est coupé, il le tue. Maxime Chattam orchestre une véritable course contre la montre où s’affrontent le cynisme des médias, les jeux de pouvoir et les scrupules moraux. Jouant avec brio sur les ressorts psychologiques autant que sur l’action, il déploie dans ce nouveau roman tout son art de maître du suspense.', '2025-01-06 15:00:00', '2025-01-06 16:00:00', 'one shot'),
('7l8m9n0o-1p2q-3r4s-5t6u-7v8w9x0y1z2a', '978-7890123457', 'iron flame', 'rebecca yarros', '2023-10-01', 25.00, 'Fantasy', 'Folio', 'images/booksImages/iron_flame.png', 'images/vignettesImages/iron_flame.png', 16, 'Tout le monde s''attendait à voir Violet Sorrengail échouer lors de sa première année à l''Académie de la guerre de Basgiath, y compris elle-même... Pourtant cette aventure endiablée n''était qu''une première épreuve, destinée à éliminer les faibles, les indignes et les malchanceux. Le véritable entraînement commence maintenant, et Violet se demande déjà comment elle va s''en sortir. Ce n''est pas seulement l''épuisement, la brutalité, ou le fait que le programme soit conçu pour pousser les cavaliers au-delà de leur capacité de résistance à la douleur. C''est surtout que le nouveau vice-commandant semble s’être donné pour mission de montrer à Violet à quel point elle est impuissante... A moins qu''elle n’accepte de trahir l''homme qu''elle aime. Mais Violet possède le plus féroce des atouts : une volonté de fer. Et elle compte bien la mettre à profit de la leçon la plus importante que Basgiath lui ait enseignée : un dragonnier établit ses propres règles !', '2025-01-07 16:00:00', '2025-01-07 17:00:00', '2 sur 2'),
('8m9n0o1p-2q3r-4s5t-6u7v-8w9x0y1z2a3b', '978-8901234568', 'La psy', 'Freida McFadden', '2022-02-14', 17.50, 'Thriller', 'Actes Sud', 'images/booksImages/la_psy.png', 'images/vignettesImages/la_psy.png', 18, 'Jeunes mariés, Tricia et Ethan recherchent la maison de leurs rêves. Alors qu''ils visitent le manoir isolé de la docteure Adrienne Hale, une psychiatre disparue trois ans plus tôt, ils se retrouvent piégés par une violente tempête de neige. Au grand effroi de Tricia, qui est persuadée que quelque chose de terrible s''est produit dans cette demeure. Et puis, il y a ces empreintes de pas récentes sur le parquet, comme si quelqu''un vivait encore là... Par hasard, Tricia découvre une pièce secrète qui renferme les enregistrements audio de chaque patient de la docteure Hale. Le voile de mystère qui recouvre la disparition de la psy se lève lentement. Mais déterrer des secrets enfouis est un jeu dangereux...', '2025-01-08 17:00:00', '2025-01-08 18:00:00', 'one shot'),
('9n0o1p2q-3r4s-5t6u-7v8w-9x0y1z2a3b4c', '978-2290391174', 'La femme de ménage', 'Freida McFadden', '2021-06-30', 16.99, 'Contemporain', 'Gallimard', 'images/booksImages/la_femme_de_menage.png', 'images/vignettesImages/la_femme_de_menage.png', 16, 'Chaque jour, Millie fait le ménage dans la belle maison des Winchester, une riche famille new-yorkaise. Elle récupère aussi leur fille à l''école et prépare les repas avant d''aller se coucher dans sa chambre, au grenier. Pour la jeune femme, ce nouveau travail est une chance inespérée. L''occasion de repartir de zéro. Mais, sous des dehors respectables, sa patronne se montre de plus en plus instable et toxique. Et puis il y a aussi cette rumeur dérangeante qui court dans le quartier : Mme Winchester aurait tenté de noyer sa fille quelques années auparavant. Heureusement, le charmant M. Winchester est là pour rendre la situation plus supportable. Mais le danger se tapit parfois sous des apparences trompeuses. Et lorsque Millie découvre que la porte de sa chambre mansardée ne ferme que de l''extérieur, il est peut-être déjà trop tard...', '2025-01-09 18:00:00', '2025-01-09 19:00:00', 'one shot'),
('0o1p2q3r-4s5t-6u7v-8w9x-0y1z2a3b4c5d', '978-2017207030', 'Lakestone tome 1', 'Sarah Rivens', '2020-04-25', 21.00, 'Fantasy', 'Plon', 'images/booksImages/Lakestone_tome_1.png', 'images/vignettesImages/Lakestone_tome_1.png', 14, 'Dans la tranquillité trompeuse de la ville d''Ewing aux États-Unis, Iris, confinée à la bibliothèque, est plongée dans ses révisions. À des kilomètres de là, un mercenaire affronte le froid tranchant de la nuit, aussi glaciale que le cadavre qu''il vient d’enterrer. Ils n’ont rien en commun, pourtant tous deux ont le même objectif : amasser assez d''argent. Iris, pour payer ses frais de scolarité à l''université, le mercenaire, pour mener à bien sa mission. Mission dont elle est la cible. Désormais, l''existence d''Iris est liée à celle de cet homme, une connexion qui éveille en lui curiosité et désir. Arrachée à la vie qu’elle a toujours connue, la jeune étudiante se retrouve à la merci du mercenaire dont l’impulsivité a forgé la réputation, celui qui a été façonné pour tuer… Celui qu’on appelait Lakestone.', '2025-01-10 19:00:00', '2025-01-10 20:00:00', '1 sur 2'),
('1p2q3r4s-5t6u-7v8w-9x0y-1z2a3b4c5d6e', '978-2017207030', 'Le sang et la cendre', 'Jennifer L. Armentrout', '2021-08-15', 23.50, 'Fantasy', 'Gallimard', 'images/booksImages/le_sang_et_la_cendre.png', 'images/vignettesImages/le_sang_et_la_cendre.png', 16, 'Alors que la rivalité grandit entre deux royaumes ennemis depuis toujours, une jeune femme dont le destin était tout tracé voit ses certitudes voler en éclats, et plus que tout... son cœur. Choisie depuis sa naissance pour inaugurer une nouvelle ère de son royaume, la vie de Poppy n''a jamais vraiment été la sienne. Ses parents ont été tués quand elle était jeune et elle vit depuis recluse et surprotégée. Une vie solitaire, sans être touchée ni même regardée, sans contact avec l''extérieur et avec un seul moment à attendre : le jour de son Élévation. L''avenir du royaume tout entier repose sur les épaules de Poppy, mais elle n''est pas sûre de vouloir de cette destinée. Parce qu''elle a un cœur, une âme et qu''elle préfèrerait combattre les créatures qui ont causé son malheur. Et quand Hawke, un garde royal chargé de la protéger jusqu''à son Élévation, fait irruption dans sa vie, il remet en question ses croyances, jusqu''à la tentation de l''interdit. Abandonné par les dieux et craint par les mortels, un autre royaume déchu se soulève, déterminé à reprendre ce qui lui est dû par la violence et la vengeance. Et alors que la menace se rapproche, Poppy est non seulement sur le point d''être jugée indigne par les dieux et de perdre son cœur, mais aussi sa propre vie à mesure que tout ce qui constituait son univers s''écroule inexorablement.​', '2025-01-11 10:00:00', '2025-01-11 11:00:00', '1 sur 3'),
('2q3r4s5t-6u7v-8w9x-0y1z-2a3b4c5d6e7f', '978-2371266391', 'A nos coeurs battants', 'emma green', '2022-12-01', 18.00, 'Romance', 'Plon', 'images/booksImages/a_nos_coeurs_battants.png', 'images/vignettesImages/a_nos_coeurs_battants.png', 14, 'Après une adolescence tumultueuse, Romeo Cruz a trouvé la vocation qui donne un sens à sa vie : il est désormais secouriste et vient en aide à la population de Chicago. Mais ce nouvel équilibre se fissure lorsque Maxima Miller revient à la caserne après trois ans d''absence. Elle est l''amie d''enfance de son frère, la femme intouchable qui l''a toujours fasciné - et celle qui les a tous lâchés du jour au lendemain. Il est des départs qui ne s‘expliquent pas... Ceux-là sont les plus difficiles à pardonner. Depuis toujours, Max semble vouloir affronter seule les épreuves qui la poursuivent. C''est pourtant vers Romeo qu''elle se tourne pour lui demander de devenir son faux petit ami. Impensable pour lui... Intenable, aussi. Mais tous deux savent trop bien comme la vie est fragile. Et qu''il faut oser s''y accrocher de toutes ses forces, tant que le coeur bat encore...', '2025-01-12 11:00:00', '2025-01-12 12:00:00', 'one shot'),
('3r4s5t6u-7v8w-9x0y-1z2a-3b4c5d6e7f8g', '978-2755677560', 'king of sin livre 1 la colére', 'ana Huang', '2023-03-20', 20.99, 'Fantasy', 'Folio', 'images/booksImages/king_of_sin_livre_1__la_colére.png', 'images/vignettesImages/king_of_sin_livre_1__la_colére.png', 16, 'Elle est la femme dont il n’a jamais voulu… et la faiblesse qu’il n’a pas vu venir. Impitoyable. Méticuleux. Arrogant. Dante Russo aime tout contrôler, sa vie privée comme professionnelle. Le PDG milliardaire n’avait jamais envisagé de se marier, jusqu’à ce qu’un chantage l’oblige à se fiancer à une femme qu’il connaît à peine : Vivian Lau, héritière d’un joaillier et fille de son nouvel ennemi. Qu’importe sa beauté ou son charme, Dante fera tout ce qui est en son pouvoir pour rompre leurs fiançailles en déjouant le chantage. Seulement il a un problème : maintenant qu’elle lui appartient... il ne peut se résoudre à la laisser partir. Élégante. Ambitieuse. Distinguée. Vivian Lau est l’atout de sa famille vers les plus hautes sphères de la société. Épouser un Russo signifie ouvrir des portes jusqu’à présent fermées aux Lau, en raison de leur statut de nouveaux riches. Elle accepte ce mariage arrangé par devoir malgré le tempérament grossier et difficile de Dante. Pourtant le désirer n’a jamais fait partie de son plan et tomber amoureuse de son futur mari serait la pire chose qui pourrait arriver.', '2025-01-13 12:00:00', '2025-01-13 13:00:00', '1 sur 2'),
('4s5t6u7v-8w9x-0y1z-2a3b-4c5d6e7f8g9h', '978-2755677416', 'valentina (tome 1)', 'Azra Reed', '2021-05-10', 19.50, 'Romance', 'Actes Sud', 'images/booksImages/valentina_tome1.png', 'images/vignettesImages/valentina_tome1.png', 14, 'Ce monde ne t’attendra pas, Valentina. Ce livre est une Dark Romance destinée à un public adulte et averti. Valentina n’aspire qu’à fuir la violence et la pauvreté de Tepito. Elle est portée par l’espoir d’un avenir meilleur, pour elle et sa grand-mère, loin des règlements de comptes meurtriers qui rythment le quotidien de son quartier. Pourtant, en voulant aider les siens, Valentina se retrouve propulsée dans le milieu sanglant des cartels, là où la peur et la haine règnent en maître. Une succession de mauvaises décisions déclenchent une guerre entre rivaux qui éradique toute possibilité de paix. Alors que Valentina sombre peu à peu dans la noirceur de ce monde sans pitié, sa seule lueur d’espoir prend les traits de l’homme qui l’a capturée : Preto, le chef du cartel des Cruz. Pour survivre, elle doit lui faire confiance, mais peut-elle vraiment se fier à lui ?', '2025-01-14 13:00:00', '2025-01-14 14:00:00', '1 sur 2'),
('5t6u7v8w-9x0y-1z2a-3b4c-5d6e7f8g9h0i', '978-2755677423', 'valentina (tome 2)', 'Azra Reed', '2022-09-15', 21.00, 'Romance', 'Gallimard', 'images/booksImages/valentina_tome2.png', 'images/vignettesImages/valentina_tome2.png', 14, 'Peu importe où tu iras, hermosa, je finis toujours par récupérer ce qui m’appartient. Ce livre est une Dark Romance destinée à un public adulte et averti. La guerre des cartels scellera-t-elle le destin de Valentina ? Prisonnière des griffes d’Angel Cortès, elle ne peut compter que sur elle-même. À moins que l’homme qui l’avait capturée ne vienne la sauver ? Pendant ce temps, rien ne semble pouvoir arrêter l''ascension fulgurante de Preto. Son ambition le pousse à ignorer tous les avertissements, quitte à attiser la convoitise de nouveaux ennemis. Au cœur de cette escalade de violence, Preto n''a pas peur de défier Angel Cortès pour récupérer celle qu''il n''arrive pas à oublier. Et s''il peut en profiter pour prendre son trône et contrôler le trafic de drogue au Mexique, il n''hésitera pas à rendre cette guerre plus que sanglante. Dans cet univers où les alliances se brisent plus vite qu’elles ne se forment, une trahison amère pourrait fragiliser les fondations mêmes du cartel. Et la rancœur de Preto n''en serait que plus profonde si elle venait de celle à qui il vient juste d''accorder sa confiance…', '2025-01-15 14:00:00', '2025-01-15 15:00:00', '2 sur 2'),
('6u7v8w9x-0y1z-2a3b-4c5d-6e7f8g9h0i1j', '978-6789012347', 'un automne pour te pardonner', 'morgane moncomble', '2020-10-05', 22.50, 'Contemporain', 'Plon', 'images/booksImages/un_automne_pour_te_pardonner.png', 'images/vignettesImages/un_automne_pour_te_pardonner.png', 16, 'Avocate en devenir, Camélia est passionnée de crimes non résolus. Ça tombe bien, Rory Cavendish, son ancien bourreau, vient de mourir mystérieusement. Le présumé coupable du meurtre, c’est lui : Lou McAllister. Le meilleur ami de Rory. Le garçon qui l’a humiliée il y a dix ans et qu’elle n’a jamais oublié depuis. Camélia saisit cette chance pour résoudre sa première enquête... et satisfaire sa soif de vengeance. Lou a toujours été le mouton noir de sa famille, mais il ne s’attendait pas à finir en prison pour meurtre. Du jour au lendemain, le voilà abandonné par tous ceux en qui il avait confiance. La seule personne à pouvoir le sortir de là, c’est elle : Camélia O''Brien. La première victime de Rory. La fille qu’il a blessée plus jeune et qui hante ses pensées depuis. Lou est prêt à tout pour se faire pardonner ses péchés... et repartir de zéro.', '2025-01-16 15:00:00', '2025-01-16 16:00:00', 'one shot'),
('7v8w9x0y-1z2a-3b4c-5d6e-7f8g9h0i1j2k', '978-2755673135', 'fourth wing', 'rebecca yarros', '2023-06-01', 24.99, 'Fantasy', 'Folio', 'images/booksImages/fourth_wing.png', 'images/vignettesImages/fourth_wing.png', 16, 'Rien ne prédestinait Violet Sorrengail à être une cavalière. Elle était censée intégrer le quadrant des Scribes et mener une vie tranquille parmi les livres. Elle dont les os sont si fragiles qu’ils peuvent se briser en un instant… Mais aujourd’hui est le jour des conscriptions, et en tant que fille de la Générale - elle-même cavalière et dresseuse de dragons -, Violet n’a d’autre choix que de satisfaire les ordres de sa mère, et de rejoindre les épreuves de sélection pour devenir dragonnière… L’élite de la Navarre !Pourtant, le simple fait d’envisager s’inscrire à cette compétition lui paraît ridicule… Car les dragons ne se lient pas aux humains « fragiles » : ils les brûlent ! Mais Violet est peut-être la candidate la moins forte physiquement, elle est cependant rusée et rapide. Des qualités indispensables quand on évolue dans un monde sans foi ni loi, où les alliés peuvent vite devenir des ennemis, ou peut-être encore des conquêtes… Violet va vite devoir penser à un plan solide, car cette compétition n’a que deux issues : passer toutes les épreuves ou mourir !', '2025-01-17 16:00:00', '2025-01-17 17:00:00', '1 sur 2'),
('8w9x0y1z-2a3b-4c5d-6e7f-8g9h0i1j2k3l', '978-2755673142', 'iron flame', 'rebecca yarros', '2023-10-01', 25.00, 'Fantasy', 'Gallimard', 'images/booksImages/iron_flame.png', 'images/vignettesImages/iron_flame.png', 16, 'Tout le monde s''attendait à voir Violet Sorrengail échouer lors de sa première année à l''Académie de la guerre de Basgiath, y compris elle-même... Pourtant cette aventure endiablée n''était qu''une première épreuve, destinée à éliminer les faibles, les indignes et les malchanceux. Le véritable entraînement commence maintenant, et Violet se demande déjà comment elle va s''en sortir. Ce n''est pas seulement l''épuisement, la brutalité, ou le fait que le programme soit conçu pour pousser les cavaliers au-delà de leur capacité de résistance à la douleur.C''est surtout que le nouveau vice-commandant semble s’être donné pour mission de montrer à Violet à quel point elle est impuissante... A moins qu''elle n’accepte de trahir l''homme qu''elle aime. Mais Violet possède le plus féroce des atouts : une volonté de fer. Et elle compte bien la mettre à profit de la leçon la plus importante que Basgiath lui ait enseignée : un dragonnier établit ses propres règles !', '2025-01-18 17:00:00', '2025-01-18 18:00:00', '2 sur 2'),
('9x0y1z2a-3b4c-5d6e-7f8g-9h0i1j2k3l4m', '978-9012345670', 'La sage femme d''Auschwitz', 'Ana Stuart', '2021-01-27', 18.50, 'Historique', 'Actes Sud', 'images/booksImages/la_sage_femme_d_auschwitz.png', 'images/vignettesImages/la_sage_femme_d_auschwitz.png', 18, 'Lorsqu''elle arrive à Auschwitz, sous un ciel bas et gris, Ana est persuadée qu''elle ne survivra pas à l''enfer du camp. Mais elle possède une compétence que les nazis recherchent : elle est sage-femme. Son travail sera de donner naissance aux enfants des autres prisonnières. Une mission terrible car, dès qu''ils ont poussé leur premier cri, les nouveau-nés sont emmenés et donnés à des familles allemandes. Malgré la détresse de ces femmes à qui on vole leurs bébés, Ana essaie d''apporter un peu de réconfort autour d''elle. Et puis un jour, elle réalise qu''elle peut faire plus. Secrètement, elle tatoue les petits avec les numéros de déportées de leurs mères. C''est une lueur d''espoir dans ce monde d''une infinie noirceur : et si, après l''horreur de la guerre, grâce à ce petit geste, ces enfants et leurs mères pouvaient se retrouver ?', '2025-01-19 18:00:00', '2025-01-19 19:00:00', 'one shot'),
('3c4d5e6f-7g8h-9i0j-1k2l-3m4n5o6p7q8r', '978-0123456781', 'Tata', 'Valérie Perrin', '2022-04-15', 20.00, 'Contemporain', 'Gallimard', 'images/booksImages/tata.png', 'images/vignettesImages/tata.png', 14, 'Colette était une femme sans histoire. C''est du moins ce que l''on croyait jusqu''au jour où sa nièce apprend son décès par un appel de la police. Car Colette, sa tante unique, a déjà été enterrée il y a trois ans... Avec ce roman virtuose où s''entrelacent destins et intrigues palpitantes, Valérie Perrin, extraordinaire conteuse de nos vies, signe son grand retour.', '2025-01-20 19:00:00', '2025-01-20 20:00:00', 'one shot');

